"""Copy docs/DECISIONS.md into web/src/content/decisions.ts so the /decisions
page ships the same text. Run after editing the markdown."""
from pathlib import Path
root = Path(__file__).resolve().parents[1]
md = (root / "docs" / "DECISIONS.md").read_text()
escaped = md.replace("\\", "\\\\").replace("`", "\\`").replace("${", "\\${")
(root / "web" / "src" / "content" / "decisions.ts").write_text(
    "// Generated by scripts/sync-decisions.py from docs/DECISIONS.md. Do not edit by hand.\n"
    f"export const DECISIONS_MD = `{escaped}`;\n"
)
print("synced", len(md), "chars")
